public class ErrorMetricsTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        check("mse({2,4}, {1,2})", 2.5, ErrorMetrics.mse(new double[]{2, 4}, new double[]{1, 2}));
        check("perfect predictions", 0.0, ErrorMetrics.mse(new double[]{1, 2, 3}, new double[]{1, 2, 3}));
        check("mse({3}, {1})", 4.0, ErrorMetrics.mse(new double[]{3}, new double[]{1}));
        check("mse({1,2,3,4}, {0,0,0,0})", 7.5, ErrorMetrics.mse(new double[]{1, 2, 3, 4}, new double[]{0, 0, 0, 0}));
        check("mse({0.5,1.5}, {0,1})", 0.25, ErrorMetrics.mse(new double[]{0.5, 1.5}, new double[]{0, 1}));
        check("negative errors square positive", 2.5, ErrorMetrics.mse(new double[]{0, 0}, new double[]{1, -2}));
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
