public class ErrorMetrics {

    public static double mse(double[] predicted, double[] actual) {
        double sum = 0.0;
        for (int i = 0; i < predicted.length; i++) {
            double diff = predicted[i] - actual[i];
            sum += diff * diff;
        }
        return sum / predicted.length;
    }
}
